-- Темы 06, 07, 12, 16: девять вопросов с одним ответом стали вопросами с несколькими ответами.
-- Источник: scripts/questions/126_multi_topics06_07_12_16.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключ ответа меняется только правкой вида key, прежний ключ проверяется; число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Что произойдёт, если не выполнять заморозку своевременно?', NULL, NULL, NULL, 'Заморозку долго не выполняли, и возраст незамороженных транзакций подошёл к пределу. Что произойдёт?'),
        ('option', 'Заморозку долго не выполняли, и возраст незамороженных транзакций подошёл к пределу. Что произойдёт?', 'Автоочистка отключится до ручного VACUUM', 'Автоочистка запустится, даже если она выключена', 'Автоочистка не отключается; защитная очистка запускается даже при выключенной автоочистке.', 'Когда возраст таблицы превышает autovacuum_freeze_max_age, сервер запускает защитную очистку от оборота счётчика даже при autovacuum = off.'),
        ('explanation', 'Заморозку долго не выполняли, и возраст незамороженных транзакций подошёл к пределу. Что произойдёт?', NULL, NULL, 'В курсе это описано как аварийная остановка сервера с обрывом незавершённых транзакций; в PostgreSQL 16 сервер продолжает работать, но отказывается выдавать новые номера транзакций. Уже начатые транзакции могут завершиться, но новые смогут только читать данные. VACUUM при этом работает, им и выполняют заморозку.', 'Сначала, при возрасте autovacuum_freeze_max_age, запускается защитная автоочистка, даже если автоочистка выключена. Если и она не успевает, сервер перестаёт выдавать новые номера транзакций: уже начатые транзакции могут завершиться, а новые смогут только читать данные. VACUUM при этом работает, им и выполняют заморозку. В курсе это описано как аварийная остановка сервера; в PostgreSQL 16 сервер продолжает работать.'),
        ('key', 'Заморозку долго не выполняли, и возраст незамороженных транзакций подошёл к пределу. Что произойдёт?', NULL, NULL, 'A', 'AD'),
        ('question', 'Возвращает ли обычный VACUUM, как правило, освободившееся место операционной системе?', NULL, NULL, NULL, 'Что верно для места, которое освободил обычный VACUUM?'),
        ('option', 'Что верно для места, которое освободил обычный VACUUM?', 'Да: файл таблицы сразу уменьшается до размера данных', 'Файл таблицы сразу уменьшается до размера данных', 'Обычно нет: системе возвращается только пустой хвост файла.', 'Обычный VACUUM не переписывает таблицу; уплотнить файл может VACUUM FULL.'),
        ('option', 'Что верно для места, которое освободил обычный VACUUM?', 'Да, если таблица занимает меньше 1 ГБ', 'Место возвращается ОС, если таблица меньше 1 ГБ', NULL, NULL),
        ('option', 'Что верно для места, которое освободил обычный VACUUM?', 'Да, но место освобождается в индексах, не в таблице', 'Пустые страницы в конце файла могут быть отрезаны', 'Нет: в B-tree освободившиеся страницы используются повторно, а файл индекса сам не уменьшается; уменьшить его можно перестроением.', 'Если в конце файла остались полностью пустые страницы, VACUUM может их отрезать и вернуть место системе. Для этого он ненадолго берёт исключительную блокировку таблицы.'),
        ('option', 'Что верно для места, которое освободил обычный VACUUM?', 'Нет: место остаётся для новых версий строк', 'Место внутри страниц остаётся для новых версий строк', 'Освободившееся место внутри страниц используется для новых версий строк; системе возвращается только пустой хвост файла.', 'Освободившееся место внутри страниц используется для новых версий строк, файл при этом не уменьшается.'),
        ('key', 'Что верно для места, которое освободил обычный VACUUM?', NULL, NULL, 'D', 'CD'),
        ('question', 'Почему изменённая страница записывается на диск не сразу?', NULL, NULL, NULL, 'Почему изменённую страницу можно не записывать на диск сразу?'),
        ('option', 'Почему изменённую страницу можно не записывать на диск сразу?', 'Чтобы записать страницы разом при остановке сервера', 'Надёжность обеспечивает журнал, а не запись страницы', 'Страницы записывают контрольные точки, фоновая запись и вытеснение, не дожидаясь остановки.', 'Записи WAL попадают на диск раньше страницы данных, и после сбоя изменение воспроизводится по журналу. Поэтому спешить с записью самой страницы не нужно.'),
        ('explanation', 'Почему изменённую страницу можно не записывать на диск сразу?', NULL, NULL, 'Отложенная запись позволяет объединять изменения страницы и уменьшать ввод-вывод; восстановление до записи страницы обеспечивает WAL.', 'Отложенная запись позволяет объединять изменения страницы и уменьшать ввод-вывод, а безопасность такой отсрочки обеспечивает журнал предзаписи.'),
        ('key', 'Почему изменённую страницу можно не записывать на диск сразу?', NULL, NULL, 'D', 'BD'),
        ('question', 'Что делает сервер при остановке в режиме fast?', NULL, NULL, NULL, 'Что верно для остановки сервера в режиме fast?'),
        ('option', 'Что верно для остановки сервера в режиме fast?', 'Перечитывает настройки и возобновляет обслуживание', 'При следующем запуске восстановление не понадобится', 'Остановка fast не является перечитыванием конфигурации или возобновлением обслуживания.', 'Перед выключением сервер выполняет контрольную точку, поэтому при следующем запуске он сразу готов к работе, без воспроизведения журнала.'),
        ('option', 'Что верно для остановки сервера в режиме fast?', 'Отключает клиентов и выполняет контрольную точку', NULL, 'Отключает клиентов, отменяя их активные транзакции, и перед выключением выполняет контрольную точку, поэтому при следующем запуске сервер сразу готов к работе.', 'Отключает клиентов, отменяя их активные транзакции, и перед выключением выполняет контрольную точку.'),
        ('key', 'Что верно для остановки сервера в режиме fast?', NULL, NULL, 'C', 'AC'),
        ('question', 'Сервер был остановлен в режиме immediate. Что произойдёт при следующем запуске?', NULL, NULL, NULL, 'Сервер с настройками по умолчанию остановили в режиме immediate. Что верно для следующего запуска?'),
        ('option', 'Сервер с настройками по умолчанию остановили в режиме immediate. Что верно для следующего запуска?', 'Журнал будет удалён', 'Подтверждённые до остановки транзакции сохранятся', 'Именно журнал нужен для восстановления.', 'При synchronous_commit = on клиент получает подтверждение COMMIT после сброса WAL на диск, поэтому восстановление вернёт эти транзакции.'),
        ('explanation', 'Сервер с настройками по умолчанию остановили в режиме immediate. Что верно для следующего запуска?', NULL, NULL, 'После immediate сервер при запуске воспроизводит WAL, чтобы восстановить согласованное состояние файлов данных.', 'После immediate сервер при запуске воспроизводит WAL, как после сбоя, и восстанавливает согласованное состояние файлов данных. Подтверждённые транзакции не теряются: их журнальные записи уже на диске.'),
        ('key', 'Сервер с настройками по умолчанию остановили в режиме immediate. Что верно для следующего запуска?', NULL, NULL, 'A', 'AB'),
        ('question', 'Какой из параметров выключен по умолчанию в Linux?', NULL, NULL, NULL, 'Какие из этих параметров выключены по умолчанию в PostgreSQL 16?'),
        ('option', 'Какие из этих параметров выключены по умолчанию в PostgreSQL 16?', 'track_counts', NULL, 'Включён по умолчанию.', 'Включён по умолчанию: без него автоочистка не узнаёт об изменениях таблиц.'),
        ('option', 'Какие из этих параметров выключены по умолчанию в PostgreSQL 16?', 'track_activities', 'log_checkpoints', 'Включён по умолчанию.', 'С версии 15 включён по умолчанию.'),
        ('option', 'Какие из этих параметров выключены по умолчанию в PostgreSQL 16?', 'update_process_title', 'log_lock_waits', 'Включён по умолчанию (кроме Windows).', 'Выключен. Если включить, в журнал попадут ожидания блокировок дольше deadlock_timeout.'),
        ('explanation', 'Какие из этих параметров выключены по умолчанию в PostgreSQL 16?', NULL, NULL, 'track_io_timing по умолчанию выключен из-за возможной стоимости измерений времени ввода-вывода.', 'track_io_timing выключен из-за возможной стоимости замеров времени, log_lock_waits — чтобы не засорять журнал. log_checkpoints с версии 15 включён по умолчанию. Проверить: SELECT name, boot_val FROM pg_settings WHERE name LIKE ''track%'' OR name LIKE ''log_%'';'),
        ('key', 'Какие из этих параметров выключены по умолчанию в PostgreSQL 16?', NULL, NULL, 'C', 'CD'),
        ('question', 'Какой параметр задаёт порог длительности для записи завершённых команд в журнал?', NULL, NULL, NULL, 'Какие настройки, каждая сама по себе, добавят в журнал длительность каждой завершённой команды?'),
        ('option', 'Какие настройки, каждая сама по себе, добавят в журнал длительность каждой завершённой команды?', 'log_autovacuum_min_duration', 'log_statement = ''all''', 'Задаёт порог для записи действий автоочистки, а не обычных команд.', 'Записывает тексты команд, но не их длительность.'),
        ('option', 'Какие настройки, каждая сама по себе, добавят в журнал длительность каждой завершённой команды?', 'log_min_error_statement', 'log_min_error_statement = error', 'Определяет, при каком уровне ошибки в журнал попадает текст команды, а не порог длительности.', 'Записывает текст команды, которая завершилась ошибкой, без длительности; error — значение по умолчанию.'),
        ('option', 'Какие настройки, каждая сама по себе, добавят в журнал длительность каждой завершённой команды?', 'log_min_duration_statement', 'log_min_duration_statement = 0', 'Записывает команды не короче порога; 0 — все, -1 — отключено.', 'Порог 0 означает все команды: в журнал попадают длительность и текст.'),
        ('option', 'Какие настройки, каждая сама по себе, добавят в журнал длительность каждой завершённой команды?', 'log_duration', 'log_duration = on', 'Записывает длительность всех завершённых команд, а не только долгих.', 'Записывает длительность каждой завершённой команды, но без её текста.'),
        ('explanation', 'Какие настройки, каждая сама по себе, добавят в журнал длительность каждой завершённой команды?', NULL, NULL, 'log_min_duration_statement журналирует завершённые команды длительностью не меньше заданного порога.', 'Для поиска долгих запросов обычно задают порог log_min_duration_statement, например 1s: в журнал попадут только долгие команды вместе с текстом. Значение -1 отключает запись.'),
        ('key', 'Какие настройки, каждая сама по себе, добавят в журнал длительность каждой завершённой команды?', NULL, NULL, 'C', 'CD'),
        ('question', 'Что происходит при конфликте (нарушении ограничения) на подписчике?', NULL, NULL, NULL, 'Изменение с издателя нарушает ограничение на подписчике. Что верно?'),
        ('option', 'Изменение с издателя нарушает ограничение на подписчике. Что верно?', 'Подписка удаляется вместе со своим слотом репликации', 'В журнал подписчика пишется ошибка о конфликте', 'Подписка остаётся.', 'Рабочий процесс подписки пишет ошибку в журнал и после перезапуска снова пробует применить то же изменение.'),
        ('explanation', 'Изменение с издателя нарушает ограничение на подписчике. Что верно?', NULL, NULL, 'Автоматического разрешения конфликтов нет.', 'Автоматического разрешения конфликтов нет: пока данные на подписчике не исправят или транзакцию не пропустят командой ALTER SUBSCRIPTION ... SKIP, применение стоит.'),
        ('key', 'Изменение с издателя нарушает ограничение на подписчике. Что верно?', NULL, NULL, 'D', 'CD'),
        ('question', 'Чем опасен неактивный слот логической репликации?', NULL, NULL, NULL, 'Слот логической репликации на издателе давно не используется, настройки по умолчанию. Чем это опасно?'),
        ('option', 'Слот логической репликации на издателе давно не используется, настройки по умолчанию. Чем это опасно?', 'Блокирует таблицы публикации для записи', 'Издатель копит сегменты WAL, и pg_wal растёт', 'Таблицы не блокируются.', 'Слот хранит позицию, с которой подписчику нужен журнал. При max_slot_wal_keep_size = -1, как по умолчанию, эти сегменты не удаляются.'),
        ('option', 'Слот логической репликации на издателе давно не используется, настройки по умолчанию. Чем это опасно?', 'Отключает автоочистку на издателе', 'Автоочистка на издателе полностью отключается', 'Автоочистка работает, но горизонт удерживается.', 'Автоочистка работает, но не может убрать версии строк каталога, нужные слоту.'),
        ('option', 'Слот логической репликации на издателе давно не используется, настройки по умолчанию. Чем это опасно?', 'Удерживает журнал и горизонт очистки', 'Очистка не убирает старые версии системного каталога', 'Сервер копит сегменты WAL и удерживает версии строк системного каталога, нужные для декодирования.', 'Логический слот удерживает горизонт очистки системного каталога: старые версии строк каталога нужны для декодирования.'),
        ('option', 'Слот логической репликации на издателе давно не используется, настройки по умолчанию. Чем это опасно?', 'Удаляет публикацию через заданное время', 'Публикация удаляется через заданное время', NULL, NULL),
        ('explanation', 'Слот логической репликации на издателе давно не используется, настройки по умолчанию. Чем это опасно?', NULL, NULL, 'Неактивный логический слот может удерживать WAL и версии системного каталога, необходимые для продолжения декодирования, вызывая рост занимаемого места.', 'Неактивный логический слот удерживает журнал и версии строк системного каталога, нужные для продолжения декодирования, и занятое место растёт. Такие слоты видно в pg_replication_slots по active = false; если подписка больше не нужна, слот удаляют функцией pg_drop_replication_slot.'),
        ('key', 'Слот логической репликации на издателе давно не используется, настройки по умолчанию. Чем это опасно?', NULL, NULL, 'C', 'AC')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'key' THEN
            PERFORM 1 FROM questions WHERE id = qid AND correct_answer IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданный ключ ответа'; END IF;
            UPDATE questions SET correct_answer = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
